with unpacked as (select id, plan, element_at(tier_prices, 1) as entry_price, aggregate(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, slice(tier_limits, 1, 2) as first_two_limits from price_tiers where plan = 'starter') select plan, case when entry_price >= 34 then 'LARGE' else 'SMALL' end as entry_price_tier, count(distinct id) as distinct_ids, round(avg(avg_tier_price), 2) as avg_avg_tier_price, round(avg(avg_tier_price), 2) as avg_avg_tier_price_2, round(sum(entry_price) / nullif(count(case when plan = 'pro' then 1 end), 0), 2) as entry_price_per_pro from unpacked group by plan, case when entry_price >= 34 then 'LARGE' else 'SMALL' end
